<div class="gs-tracking-split"><div><h3>{{ __('govtracking::general.monitor.suppliers') }}</h3>
    @forelse(collect($receipts)->filter(fn($r)=>$r['supplier'])->groupBy('supplier')->sortByDesc(fn($r)=>$r->sum('value')) as $supplier=>$group)<p class="gs-tracking-office-rank"><strong>{{ $supplier }}</strong><span>{{ \GovStore\Tracking\Services\TrackingMonitorMetrics::money($group->contains(fn($r)=>$r['value']===null) ? null : $group->sum('value')) }}</span></p>@empty<p class="gs-tracking-muted">{{ __('govtracking::general.monitor.unavailable') }}</p>@endforelse
